SET NAMES utf8mb4;

-- ---------------------------------------------------------------------------
-- Operations workflow console (2026-10-22, requirements/20261021/platform-support-工作流; decision
-- agent-docs/decisions/2026-10-22-workflow-into-platform-support.md).
-- Self-contained block: on an environment already initialized by platform-support-initial-data.sql, apply ONLY this block.
-- Requires the ten workflow tables (changes/2026-10-22-workflow.sql) and the Delivery SES account SES_PRIMARY
-- (900000000000070001) for the WORKFLOW_NOTIFICATION email route.
-- Adds the seven WORKFLOW_* permissions and their PLATFORM_ADMIN grants (REVOKED). Platform rechecks every permission;
-- WORKFLOW_INSTANCE_READ (all instances) and WORKFLOW_INSTANCE_MANAGE (terminate others, transfer for others) are only
-- checked inside Platform and on buttons, except the callback retry route, which is bound to WORKFLOW_INSTANCE_MANAGE.
-- The assignee search route is bound to WORKFLOW_TASK_HANDLE (Platform also accepts WORKFLOW_DEFINITION_MANAGE, but a
-- route binds one permission; designers need WORKFLOW_TASK_HANDLE to use the picker through the Gateway).
-- Dormant like earlier Operations features: permissions ACTIVE, administrator grants REVOKED, menu group/menus/buttons/
-- routes DISABLED; activate them in a separate reviewed change. The Delivery template WORKFLOW_NOTIFICATION, its zh-CN
-- content and route are ACTIVE: they only send when a workflow NOTIFY rule fires, which needs the dormant routes.
-- BFF routes forward to operations-console-bff on the same paths (/workflow-admin/v1/**, /workflow/v1/**), which
-- forwards to platform-support-service; operator identity comes from the Gateway actor headers.
-- The menu group 工作流 is a top-level OPERATIONS menu (sort 60); menus and component keys follow
-- operations-console-web/src/navigation/pageCapabilities.ts.
-- Request bodies are capped at 65536 bytes (Gateway absolute ceiling), including saved drafts with the graph.
-- Workflow file routes (technique 7 #20 re-verify, #26 upload start, #27 upload completion, #28 attachment download,
-- 2026-10-22 file segment) are bound to WORKFLOW_TASK_HANDLE; Platform checks the assignee, uploader and instance
-- participant. Upload start body limit 4096, the three bodyless commands 1024; attachment routes allow 30 calls per
-- minute per operator (one start plus one completion per file). Their responses carry short-lived storage URLs; the
-- /workflow prefix is metadata-only logged in BFF and Platform. Incremental script for an environment that already has
-- the first 364 rows: requirements/20261021/platform-support-工作流/verification/local-e2e/40-workflow-file-routes.sql.
-- Rows: permission 7, role_permission 7, console_resource 10, gateway_route 32, route_header 136,
-- query_param 29, guard_rule 192, notification_template 1, notification_template_content 1, notification_route 1
-- (416). ID block 127: 1271xx permission, 1272xx role_permission, 1273xx console_resource, 1274xx route,
-- 1275xx-1276xx route_header, 1270xx query_param, 12708x notification template/content/route, 1277xx-1278xx guard_rule.
-- Rollback: delete the rows by the 900000000000127001-900000000000127999 IDs below (children first: guard_rule,
-- query_param, route_header, gateway_route, console_resource, role_permission, permission; notification_route,
-- notification_template_content, notification_template). Workflow tables keep their own data.
-- ---------------------------------------------------------------------------
START TRANSACTION;

SET @workflow_console_time = UTC_TIMESTAMP(6);
SET @workflow_console_actor_id = 1;
SET @workflow_console_target_id = 900000000000000001;
SET @workflow_console_role_id = 900000000000000510;








-- Delivery template for workflow NOTIFY rules (workflow.notification-template-code); parameters instanceTitle, nodeName,
-- trigger come from WorkflowNotificationHandler. Not transient: delivered through the ordinary notification queue.
    template_id, template_code, medium, status, version, create_time, update_time
) VALUES
    (900000000000127081, 'WORKFLOW_NOTIFICATION', 'EMAIL', 'ACTIVE', 1, @workflow_console_time, @workflow_console_time);

    content_id, template_id, locale, subject_template, body_template, version, create_time, update_time
) VALUES
    (900000000000127082, 900000000000127081, 'zh-CN', 'PAYTECH · 工作流通知：${instanceTitle}',
        CONCAT('工作流有新动态', CHAR(10), CHAR(10), '实例：${instanceTitle}', CHAR(10), '节点：${nodeName}', CHAR(10),
            '事件：${trigger}', CHAR(10), CHAR(10), '请登录运营后台的「工作流 · 我的待办」查看并处理。'),
        1, @workflow_console_time, @workflow_console_time);

    route_id, notification_template_id, primary_provider_id, fallback_provider_id, status, version,
    create_time, update_time
) VALUES
    (900000000000127083, 900000000000127081, 900000000000070001, NULL, 'ACTIVE', 1, @workflow_console_time, @workflow_console_time);

COMMIT;
